import type { CheckboxProps, CheckedState } from "./checkbox.types";

import {
  CheckSolid as CheckIcon,
  SubtractSolid as CheckIndeterminateIcon,
} from "@exp-textura/icons";
import { useTheme } from "@theme";
import * as RadixCheckbox from "@radix-ui/react-checkbox";
import { forwardRef, useState, useEffect, useCallback } from "react";
import { clsx } from "clsx";

import { CheckboxClasses, StyledCheckbox, StyledCheckboxVisual } from "./checkbox.styles";

const Checkbox = forwardRef(
  (
    {
      className,
      checked: controlledChecked,
      onCheckedChange,
      disabled,
      id,
      presentational,
      styleSlots,
      variant,
      ...props
    }: CheckboxProps,
    ref: React.ForwardedRef<HTMLButtonElement | HTMLDivElement>,
  ) => {
    const theme = useTheme();

    // Internal state for uncontrolled checkbox
    const [checked, setChecked] = useState<CheckedState>(controlledChecked ?? false);

    const handleCheckedChange = useCallback(
      (newChecked: CheckedState) => {
        if (controlledChecked === undefined) {
          setChecked(newChecked);
        }
        onCheckedChange?.(newChecked);
      },
      [controlledChecked, onCheckedChange],
    );

    useEffect(() => {
      if (controlledChecked !== undefined) {
        setChecked(controlledChecked);
      }
    }, [controlledChecked]);

    const rootClasses = clsx(CheckboxClasses.root, className);

    const icons = (
      <>
        {checked === "indeterminate" && <CheckIndeterminateIcon />}
        {checked === true && <CheckIcon />}
      </>
    );

    if (presentational) {
      return (
        <StyledCheckboxVisual
          ref={ref as React.ForwardedRef<HTMLDivElement>}
          className={rootClasses}
          currentTheme={theme}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
          checked={checked}
          data-disabled={disabled}
          data-state={
            checked === "indeterminate" ? "indeterminate" : checked ? "checked" : "unchecked"
          }
          disabled={disabled}
        >
          <div className={CheckboxClasses.indicator}>{icons}</div>
        </StyledCheckboxVisual>
      );
    }

    return (
      <StyledCheckbox
        ref={ref as React.ForwardedRef<HTMLButtonElement>}
        className={rootClasses}
        currentTheme={theme}
        styleSlots={styleSlots}
        variant={variant}
        {...props}
        checked={checked}
        disabled={disabled}
        id={id}
        onCheckedChange={handleCheckedChange}
      >
        <RadixCheckbox.Indicator className={CheckboxClasses.indicator}>
          {icons}
        </RadixCheckbox.Indicator>
      </StyledCheckbox>
    );
  },
);

Checkbox.displayName = "Checkbox";
export default Checkbox;
